create table if not exists public.integration_normalized_records (id uuid primary key default gen_random_uuid(),organization_id uuid not null,data_source_id uuid not null references public.data_sources(id) on delete cascade,sync_run_id uuid references public.data_sync_runs(id) on delete set null,source_entity_type text not null,source_record_key text not null,transaction_date date,journal_no text,description text,account_external_id text,account_code text,account_name text,debit_minor bigint not null default 0,credit_minor bigint not null default 0,currency char(3) not null default 'SAR',dimensions jsonb not null default '{}'::jsonb,source_payload jsonb not null,normalization_status text not null default 'normalized' check (normalization_status in ('normalized','needs_review','rejected')),normalization_message text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(data_source_id,source_entity_type,source_record_key)); create index if not exists idx_integration_normalized_org_date on public.integration_normalized_records(organization_id,transaction_date); create index if not exists idx_integration_normalized_source_run on public.integration_normalized_records(data_source_id,sync_run_id); alter table public.integration_normalized_records enable row level security; drop policy if exists integration_normalized_select on public.integration_normalized_records; create policy integration_normalized_select on public.integration_normalized_records for select to authenticated using (exists(select 1 from public.organization_members om where om.organization_id=integration_normalized_records.organization_id and om.user_id=auth.uid())); revoke all on table public.integration_normalized_records from anon,authenticated; grant select on table public.integration_normalized_records to authenticated;